body:
@DanStevens, this should get you started:
```PowerShell
function Update-GodotWingetSharp {
    $linksDir = "$env:LOCALAPPDATA\Microsoft\WinGet\Links"
    $godotSymlink = "$linksDir\godot.exe"
    $junctionPath = "$linksDir\GodotSharp"

    # CASE 1: Godot uninstalled - clean up orphaned junction
    if (!(Test-Path $godotSymlink)) {
        if (Test-Path $junctionPath) {
            $junctionTarget = (Get-Item $junctionPath).Target
            Write-Host "Godot uninstalled - removing orphaned junction:" -ForegroundColor Yellow
            Write-Host "  Junction: $junctionPath" -ForegroundColor Gray
            Write-Host "  Target:   $junctionTarget" -ForegroundColor Gray
            Remove-Item $junctionPath -Force -ErrorAction SilentlyContinue
            Write-Host "✓ Orphaned junction removed" -ForegroundColor Green
        }
        else {
            Write-Host "Godot not installed - nothing to do" -ForegroundColor Cyan
        }
        return
    }

    # CASE 2: Godot installed - update junction
    $realGodotExe = (Get-Item $godotSymlink).Target
    $realGodotDir = Split-Path $realGodotExe -Parent
    $realGodotSharp = Join-Path $realGodotDir "GodotSharp"

    if (!(Test-Path $realGodotSharp)) {
        Write-Warning "GodotSharp not found at $realGodotSharp (corrupt install?)"
        return
    }

    $needsUpdate = $false

    if (Test-Path $junctionPath) {
        $junctionTarget = (Get-Item $junctionPath).Target
        if (!(Test-Path $junctionTarget)) {
            Write-Host "Old junction target missing: $junctionTarget" -ForegroundColor Yellow
            $needsUpdate = $true
        }
        elseif ($junctionTarget -ne $realGodotSharp) {
            Write-Host "Junction target outdated:" -ForegroundColor Yellow
            Write-Host "  Old: $junctionTarget" -ForegroundColor Gray
            Write-Host "  New: $realGodotSharp" -ForegroundColor Cyan
            $needsUpdate = $true
        }
        else {
            Write-Host "Junction already correct: $junctionTarget" -ForegroundColor Green
            return
        }
    }
    else {
        Write-Host "No existing junction found, creating new one." -ForegroundColor Cyan
        $needsUpdate = $true
    }

    if ($needsUpdate) {
        Remove-Item $junctionPath -Force -ErrorAction SilentlyContinue
        $result = cmd /c "mklink /D `"$junctionPath`" `"$realGodotSharp`" 2>&1"
        if ($LASTEXITCODE -eq 0) {
            Write-Host "✓ Junction updated successfully" -ForegroundColor Green
        }
        else {
            Write-Error "mklink failed: $result"
        }
    }
}
Update-GodotWingetSharp
```

This creates a junction in the Links directory, updates it if godot is updated, or removes it if godot is uninstalled.
